import ctypes
import os
from django.http import JsonResponse
from django.views import View
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
import json

# Native memory management for high-performance buffer pool
libc = ctypes.CDLL('libc.so.6')
libc.malloc.restype = ctypes.c_void_p
libc.malloc.argtypes = [ctypes.c_size_t]
libc.free.argtypes = [ctypes.c_void_p]
libc.free.restype = None
libc.memcpy.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_size_t]
libc.memcpy.restype = ctypes.c_void_p

class NativeBuffer:
    """High-performance native buffer for processing large payloads"""
    def __init__(self, size):
        self.size = size
        self.ptr = libc.malloc(size)
        self._freed = False
        if not self.ptr:
            raise MemoryError("Failed to allocate buffer")

    def write(self, data):
        if self._freed:
            raise ValueError("Buffer already freed")
        raw = data.encode('utf-8') if isinstance(data, str) else data
        length = min(len(raw), self.size)
        src = (ctypes.c_char * length).from_buffer_copy(raw)
        libc.memcpy(self.ptr, ctypes.addressof(src), length)
        return length

    def release(self):
        if self.ptr:
            libc.free(self.ptr)
            self._freed = True
            # BUG: ptr not set to None after free

    def __del__(self):
        # Destructor also frees - causes double-free if release() was called
        if self.ptr:
            libc.free(self.ptr)


# Global buffer pool with LRU eviction
_buffer_pool = {}

class DataIngestionView(APIView):
    """Endpoint for high-throughput sensor data ingestion.
    Processes raw binary payloads using native buffers for performance.
    """

    def post(self, request):
        session_id = request.headers.get('X-Session-ID', '')
        payload = request.body

        if not payload:
            return Response({'error': 'Empty payload'}, status=status.HTTP_400_BAD_REQUEST)

        if len(payload) > 1048576:  # 1MB limit
            return Response({'error': 'Payload too large'}, status=status.HTTP_413_REQUEST_ENTITY_TOO_LARGE)

        try:
            buf = NativeBuffer(len(payload) + 256)
            written = buf.write(payload)

            # Store in pool for potential follow-up requests
            if session_id:
                # Evict old buffer if exists
                if session_id in _buffer_pool:
                    old_buf = _buffer_pool[session_id]
                    old_buf.release()  # First free via release()
                    # old_buf goes out of scope later -> __del__ -> second free

                _buffer_pool[session_id] = buf
            else:
                buf.release()

            return Response({
                'status': 'ingested',
                'bytes_written': written,
                'session_id': session_id
            }, status=status.HTTP_201_CREATED)

        except MemoryError:
            return Response({'error': 'Buffer allocation failed'}, status=status.HTTP_503_SERVICE_UNAVAILABLE)
        except Exception as e:
            return Response({'error': str(e)}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)

    def delete(self, request):
        """Flush a session buffer explicitly"""
        session_id = request.headers.get('X-Session-ID', '')
        if session_id in _buffer_pool:
            buf = _buffer_pool.pop(session_id)
            buf.release()  # First free
            # buf.__del__ will fire when refcount hits 0 -> double free
            del buf
            return Response({'status': 'flushed'}, status=status.HTTP_200_OK)
        return Response({'error': 'Session not found'}, status=status.HTTP_404_NOT_FOUND)


class HealthCheckView(View):
    def get(self, request):
        return JsonResponse({
            'status': 'healthy',
            'pool_size': len(_buffer_pool),
            'pid': os.getpid()
        })
